package com.northstar.crm.ui;
import com.northstar.crm.domain.*;import com.northstar.crm.security.ActorResolver;import com.northstar.crm.service.*;import com.vaadin.flow.component.*;import com.vaadin.flow.component.button.Button;import com.vaadin.flow.component.combobox.ComboBox;import com.vaadin.flow.component.html.*;import com.vaadin.flow.component.orderedlayout.*;import com.vaadin.flow.component.upload.Upload;import com.vaadin.flow.component.upload.receivers.MemoryBuffer;import com.vaadin.flow.router.*;import com.vaadin.flow.server.StreamResource;import jakarta.annotation.security.RolesAllowed;import java.io.*;import java.time.LocalDate;import java.util.*;import static com.northstar.crm.domain.DomainTypes.Role;
@Route(value="transfer",layout=MainLayout.class)@PageTitle("Reports & transfer · Northstar")@RolesAllowed({"PLATFORM_ADMIN","ACCOUNT_MANAGER","SUPPORT_AGENT"})public class ImportExportView extends VerticalLayout {public ImportExportView(ImportExportService transfer,OrganizationService organizations,ActorResolver actors){var actor=actors.current();var cards=new Div();cards.addClassName("transfer-grid");if(actor.getRole()==Role.PLATFORM_ADMIN){cards.add(exportCard("Renewal risk","Organizations renewing in the next 180 days, including billing contact.","renewals.csv",()->transfer.exportRenewals(LocalDate.now(),LocalDate.now().plusDays(180))),exportCard("Customer health","Current health assessment and internal risk summary.","customer-health.csv",transfer::exportHealth),exportCard("Escalations","Request state and severity; internal notes are excluded.","escalations.csv",transfer::exportEscalations));}else cards.add(infoCard("Scoped reporting","Platform-wide sensitive exports require platform admin access. Your dashboards and queues remain scoped to assigned accounts."));if(actor.getRole()==Role.PLATFORM_ADMIN||actor.getRole()==Role.ACCOUNT_MANAGER){var org=new ComboBox<Organization>("Organization");org.setItems(organizations.search(""));org.setItemLabelGenerator(Organization::getName);var buffer=new MemoryBuffer();var upload=new Upload(buffer);upload.setAcceptedFileTypes("text/csv",".csv");upload.setMaxFileSize(2_000_000);var result=new Paragraph();upload.addSucceededListener(e->{try{if(org.getValue()==null)throw new IllegalArgumentException("Choose an organization first");var r=transfer.importContacts(org.getValue().getId(),e.getFileName(),buffer.getInputStream().readAllBytes());result.setText(r.imported()+" contacts imported"+(r.errors().isEmpty()?"":"; "+r.errors().size()+" rows rejected"));result.getElement().getThemeList().add(r.errors().isEmpty()?"success":"warning");}catch(Exception ex){UiKit.error(ex);}});var xmlBuffer=new MemoryBuffer();var xmlUpload=new Upload(xmlBuffer);xmlUpload.setAcceptedFileTypes("application/xml","text/xml",".xml");xmlUpload.setMaxFileSize(2_000_000);var xmlResult=new Paragraph();xmlUpload.addSucceededListener(e->{try{if(org.getValue()==null)throw new IllegalArgumentException("Choose an organization first");var r=transfer.importContactsXml(org.getValue().getId(),xmlBuffer.getInputStream().readAllBytes());xmlResult.setText(r.imported()+" contacts imported from the partner feed"+(r.errors().isEmpty()?"":"; "+r.errors().size()+" records rejected"));xmlResult.getElement().getThemeList().add(r.errors().isEmpty()?"success":"warning");}catch(Exception ex){UiKit.error(ex);}});var importPanel=new VerticalLayout(new H2("Import contacts"),new Paragraph("CSV columns: name, email, phone, title, billing_contact, portal_access. Rows are validated independently."),org,upload,result,new H3("Import from partner XML"),new Paragraph("Partner extracts arrive as <contact> elements carrying the same fields as the CSV columns."),xmlUpload,xmlResult);var bundleBuffer=new MemoryBuffer();var bundlePicker=new Upload(bundleBuffer);bundlePicker.setAcceptedFileTypes("application/zip",".zip");bundlePicker.setMaxFileSize(2_000_000);var bundleResult=new Paragraph();bundlePicker.addSucceededListener(e->{try{if(org.getValue()==null)throw new IllegalArgumentException("Choose an organization first");var zr=transfer.importContactsArchive(org.getValue().getId(),bundleBuffer.getInputStream().readAllBytes());bundleResult.setText(zr.imported()+" contacts imported from the partner bundle"+(zr.errors().isEmpty()?"":"; "+zr.errors().size()+" rows rejected"));}catch(Exception ex){UiKit.error(ex);}});importPanel.add(new H3("Import from partner bundle"),new Paragraph("Compressed bundles contain one CSV contact sheet."),bundlePicker,bundleResult);var sheetName=new com.vaadin.flow.component.textfield.TextField("Delivery file name");sheetName.setPlaceholder("aster-contacts.csv");var sheetResult=new Paragraph();var sheetButton=UiKit.primary("Write contact sheet",e->{try{if(org.getValue()==null)throw new IllegalArgumentException("Choose an organization first");sheetResult.setText("Written to "+transfer.exportContactSheet(org.getValue().getId(),sheetName.getValue()));}catch(Exception ex){UiKit.error(ex);}});importPanel.add(new H3("Prepare delivery bridge file"),new Paragraph("Write the scoped contact sheet into the storage folder for the partner file bridge."),sheetName,sheetButton,sheetResult);var reportSource=new com.vaadin.flow.component.textfield.TextField("Report source");reportSource.setWidthFull();var reportLayout=new com.vaadin.flow.component.textfield.TextField("Layout");var reportResult=new Paragraph();var reportButton=UiKit.primary("Render report PDF",e->{try{var bytes=transfer.renderReportPdf(reportSource.getValue(),reportLayout.getValue());reportResult.setText("Rendered "+bytes.length+" bytes");}catch(Exception ex){UiKit.error(ex);}});importPanel.add(new H3("Render partner report"),new Paragraph("Convert the approved report source into a PDF for the partner hand-off."),reportSource,reportLayout,reportButton,reportResult);var feedName=new com.vaadin.flow.component.textfield.TextField("Contact name");var feedResult=new Paragraph();var feedButton=UiKit.primary("Search partner feed",e->{try{var hits=transfer.findFeedContact(feedName.getValue());feedResult.setText(hits.isEmpty()?"No matching contact":hits.size()+" matching records");}catch(Exception ex){UiKit.error(ex);}});importPanel.add(new H3("Search partner feed"),new Paragraph("Look up a contact in the most recent partner XML extract."),feedName,feedButton,feedResult);importPanel.addClassName("panel");cards.add(importPanel);}add(UiKit.page("CONTROLLED DATA MOVEMENT","Reports & transfer","Imports are bounded and validated; sensitive exports are scoped and audited once per request.",cards));setPadding(false);setSizeFull();}private Div exportCard(String title,String copy,String file,Source source){var link=new Anchor(new StreamResource(file,()->new ByteArrayInputStream(source.get())),"Download CSV");link.getElement().setAttribute("download",true);var d=new Div(new H3(title),new Paragraph(copy),link);d.addClassName("transfer-card");return d;}private Div infoCard(String title,String text){var d=new Div(new H3(title),new Paragraph(text));d.addClassName("transfer-card");return d;}@FunctionalInterface interface Source{byte[] get();}}
